d: rgba(74, 124, 63, 0.15);\r\n  color: #4a7c3f;\r\n  border: 1px solid rgba(74, 124, 63, 0.2);\r\n}\r\n.status-off {\r\n  background: rgba(120, 120, 120, 0.15);\r\n  color: #7a7a7a;\r\n  border: 1px solid rgba(120, 120, 120, 0.2);\r\n}\r\n.status-sleep {\r\n  background: rgba(120, 100, 160, 0.15);\r\n  color: #7a6a9a;\r\n  border: 1px solid rgba(120, 100, 160, 0.25);\r\n}\r\n\r\n/* 英灵殿档案迷你数值（英灵共鸣系统 v2） */\r\n.hero-card-stats {\r\n  display: flex;\r\n  gap: 8px;\r\n  margin-top: 4px;\r\n}\r\n.mini-stat {\r\n  font-size: 9px;\r\n  color: #8b7355;\r\n  background: rgba(201, 169, 110, 0.1);\r\n  border: 1px solid rgba(139, 90, 43, 0.18);\r\n  border-radius: 4px;\r\n  padding: 0 6px;\r\n  line-height: 1.6;\r\n  letter-spacing: 0.3px;\r\n}\r\n.mini-stat--full {\r\n  color: #8a6a10;\r\n  background: rgba(240, 212, 138, 0.25);\r\n  border-color: rgba(201, 169, 110, 0.5);\r\n  font-weight: 700;\r\n}\r\n\r\n.hero-card-arrow {\r\n  font-size: 14px;\r\n  color: #a0845c;\r\n  opacity: 0.4;\r\n}\r\n\r\n/* ---- 空状态 ---- */\r\n.empty-state {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  padding: 20px 12px;\r\n  text-align: center;\r\n}\r\n.empty-rune {\r\n  font-size: 28px;\r\n  color: #a0845c;\r\n  opacity: 0.3;\r\n  margin-bottom: 8px;\r\n}\r\n.empty-desc {\r\n  font-size: 13px;\r\n  color: #8b7355;\r\n  margin: 0;\r\n}\r\n.empty-hint {\r\n  font-size: 11px;\r\n  color: #b8a58a;\r\n  margin: 4px 0 0;\r\n  font-style: italic;\r\n}\r\n\r\n/* ---- 标签切换栏 ---- */\r\n.tab-bar {\r\n  display: flex;\r\n  gap: 6px;\r\n  padding: 4px 12px 0;\r\n  flex-shrink: 0;\r\n}\r\n.tab-btn {\r\n  flex: 1;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 6px;\r\n  padding: 6px 10px;\r\n  border: 1px solid rgba(139, 90, 43, 0.2);\r\n  border-radius: 8px 8px 0 0;\r\n  background: linear-gradient(180deg, rgba(245, 222, 179, 0.3), rgba(220, 190, 150, 0.15));\r\n  color: #6a4a2a;\r\n  font-family: 'Georgia', 'Noto Serif SC', serif;\r\n